from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]; self.errs=[]
        self.void={'meta','link','img','br','hr','input','source','area','base','col','embed','param','track','wbr','path','circle','rect','line','polygon','use','stop'}
    def handle_starttag(self,tag,attrs):
        if tag not in self.void: self.stack.append((tag,self.getpos()))
    def handle_endtag(self,tag):
        if tag in self.void: return
        if not self.stack: self.errs.append(('extra close',tag,self.getpos())); return
        if self.stack[-1][0]!=tag:
            self.errs.append(('mismatch',tag,self.getpos(),'open',self.stack[-1]))
            # try find
            for i in range(len(self.stack)-1,-1,-1):
                if self.stack[i][0]==tag:
                    del self.stack[i:]; break
        else: self.stack.pop()
p=P()
s=open('index.html',encoding='utf-8').read()
p.feed(s)
print('errors:',p.errs[:10])
print('unclosed:',p.stack[:10])
# CSS brace balance
import re
css=re.search(r'<style>(.*?)</style>',s,re.S).group(1)
print('css braces',css.count('{'),css.count('}'))
print('size',len(s))
