        print('=====',name)
        data=pg.evaluate("""() => {
          const out={};
          const h1=document.querySelector('.hero h1');
          const cs=getComputedStyle(h1);
          out.h1={w:h1.clientWidth,h:h1.clientHeight,fs:cs.fontSize,lh:cs.lineHeight,font:cs.fontFamily,weight:cs.fontWeight};
          const role=document.querySelector('.hero-role');
          out.role={w:role.clientWidth,h:role.clientHeight,fs:getComputedStyle(role).fontSize};
          const copy=document.querySelector('.pf-copy h3');
          out.pfh3={w:copy.clientWidth,h:copy.clientHeight,fs:getComputedStyle(copy).fontSize};
          const term=document.querySelector('.term-body');
          out.term={h:term.clientHeight, scroll:term.scrollHeight, w:term.clientWidth};
          // each mock section boxes
          out.mock=[...document.querySelectorAll('.mock-side,.mock-main,.mock-files,.mock-stream')].map(e=>({c:e.className,w:e.clientWidth,h:e.clientHeight,sw:e.scrollWidth,sh:e.scrollHeight}));
          // current date color checks
          out.colors={
            canvas:getComputedStyle(document.body).backgroundColor,
            primary:getComputedStyle(document.querySelector('.btn-primary')).backgroundColor,
            contact:getComputedStyle(document.querySelector('.contact-card')).backgroundColor,
            footer:getComputedStyle(document.querySelector('.site-footer')).backgroundColor,
          };
          // check contact link widths
          out.cl=[...document.querySelectorAll('.contact-link')].map(e=>({w:e.clientWidth,h:e.clientHeight,sw:e.scrollWidth}));
          return out;
        }""")
        import json; print(json.dumps(data,ensure_ascii=False,indent=1))
        pg.close()
    b.close()
